import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.Cv-B11KK.js";const k=JSON.parse('{"title":"CI and releases","description":"","frontmatter":{},"headers":[],"relativePath":"dev/releases.md","filePath":"dev/releases.md","lastUpdated":1790340653000}'),n={name:"dev/releases.md"};function o(r,e,c,l,h,d){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="ci-and-releases" tabindex="-1">CI and releases <a class="header-anchor" href="#ci-and-releases" aria-label="Permalink to &quot;CI and releases&quot;">​</a></h1><p>bbtex supports Apple Silicon Macs. Checks run locally on an Apple Silicon Mac with <code>scripts/ci.sh</code>; the GitHub Actions workflows are kept but run only when started by hand (Actions → workflow → Run workflow), because Actions minutes are limited on this private repository.</p><h2 id="local-ci" tabindex="-1">Local CI <a class="header-anchor" href="#local-ci" aria-label="Permalink to &quot;Local CI&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/ci.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # check HEAD</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/ci.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --report</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # ... and post the result on GitHub</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/ci.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --engines</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> REF</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # also compile the corpus with real TeX engines</span></span></code></pre></div><p>The script checks out the commit into a temporary git worktree, so uncommitted changes in your working folder never affect the result, then runs:</p><ol><li><code>dune build</code> and <code>dune runtest</code> (unit and cram tests).</li><li>Integration checks that need no editor session: project builds, preview cancellation, the snippet page, and draft-release gating.</li><li>shellcheck and <code>bash -n</code> on every script, <code>perl -c</code> on the preview lock, and <code>git diff --check</code> on the commit&#39;s changes relative to <code>main</code>.</li><li>The release package: <code>test/integration/check_preview_release.sh</code>, an arm64 architecture check, and a check that the binary links only system libraries. The package ZIP, its SHA-256 checksum and build information (commit, macOS, OCaml, dune and uv versions) are written to <code>dist/release/</code>. Staged installation checks also cover renamed package discovery, nested command conflicts, attachment receipts, protected upgrades and removal without touching the real BBEdit support folder.</li><li>With <code>--engines</code>: the article/book/Beamer corpus with pdfLaTeX, XeLaTeX and LuaLaTeX, including BibTeX/Biber and Poppler. With <code>--tectonic</code>: the Tectonic tier with the same pinned bundle as the GitHub workflow. That bundle&#39;s biblatex needs Biber 2.17 (MacTeX&#39;s newer Biber refuses its files), so the script downloads Biber 2.17 once, checks its SHA-256, and caches it in <code>~/Library/Caches/bbtex/biber-2.17/</code>; see <a href="./real-engine-regressions">real-engine coverage</a>.</li></ol><p><code>--report</code> posts the commit status <code>local-ci/macos-arm64</code> (or <code>local-ci/macos-arm64+engines</code>) through <code>gh</code>, so pull requests show the local result. Statuses use no Actions minutes. The output of every step goes to a log next to the temporary checkout; a failing run keeps both for inspection (<code>--keep</code> keeps them after a pass too). The script notes when the local OCaml differs from the version CI pins (<code>OCAML_COMPILER</code> in <code>.github/workflows/ci.yml</code>).</p><p>Skim, save attachments, and native focus/selection checks remain separate local integration tests (<code>BBTEX_TEST_NATIVE=1</code>). Packages are built and tested on the macOS version of the Mac running the checks; older versions are unverified.</p><h2 id="prepare-a-release" tabindex="-1">Prepare a release <a class="header-anchor" href="#prepare-a-release" aria-label="Permalink to &quot;Prepare a release&quot;">​</a></h2><ol><li><p>Update <a href="/bbtex/changelog">release notes</a>, complete the native checks, and merge the intended changes into <code>main</code>.</p></li><li><p>Set the version in <code>lib/version.ml</code> (the binary and the docs site read it there; the cram test checks <code>bbtex --version</code>), the README version badge, the heading in <code>docs/changelog.md</code> and the first line of the release notes. Merge that, then create and push an annotated tag:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.1.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;bbtex v0.1.0&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.1.0</span></span></code></pre></div></li><li><p>Run <code>scripts/ci.sh --engines --report --release v0.1.0 v0.1.0</code>. After every check passes, it creates or updates a <strong>draft</strong> GitHub release with the arm64 package ZIP, checksum and build information. It refuses to change a release that is already published. Publishing the draft is manual.</p></li><li><p>Mirror the release and its docs to the UMN copy: <code>scripts/mirror-release.sh v0.1.0</code>. Only the tag, <code>main</code> at the tagged commit and the tag&#39;s docs are pushed there.</p></li></ol>`,10)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
